<template>
  <main class="home-shell">
    <section class="hero"><div class="hero-top"><span class="brand-mark">N</span><span class="brand">LIVE NEWS</span><button class="search-trigger" @click="showSearch = true"><van-icon name="search" /></button></div><p class="eyebrow"><i></i> LIVE INTELLIGENCE</p><h1>此刻，正在发生</h1><div class="hero-footer"><span>实时聚合</span><span class="live-dot">LIVE</span></div></section>
    <section class="control-panel"><div class="mode-row"><span>实时资讯流</span><van-switch :model-value="newsStore.liveMode" size="22px" active-color="#7c5cff" @update:model-value="newsStore.setLiveMode" /></div><div class="category-scroller"><button v-for="category in newsStore.categories" :key="category.id" :class="{ active: newsStore.currentCategory === category.id }" @click="newsStore.changeCategory(category.id)">{{ category.name }}</button></div></section>
    <section v-if="newsStore.trending.length" class="trend-strip"><span class="trend-label">热</span><div class="trend-text">{{ newsStore.trending[0].title }}</div><van-icon name="arrow" /></section>
    <section class="feed-head"><div><strong>为你精选</strong><small>{{ updateLabel }}</small></div><button @click="refresh"><van-icon name="replay" /> 刷新</button></section>
    <van-pull-refresh v-model="newsStore.refreshing" @refresh="refresh"><van-list v-model:loading="newsStore.loading" :finished="newsStore.finished" finished-text="已经看到最后一条" @load="newsStore.getNewsList()"><news-item v-for="(item, index) in newsStore.newsList" :key="item.id" :news="item" :index="index" /></van-list><div v-if="!newsStore.loading && !newsStore.newsList.length" class="empty-state"><van-icon name="warning-o" /><p>暂未获取到新闻</p><button @click="refresh">重新连接</button></div></van-pull-refresh>
    <tab-bar /><van-popup v-model:show="showSearch" position="top" round><form class="search-box" @submit.prevent="doSearch"><van-icon name="search" /><input v-model="keyword" autofocus placeholder="输入关键词，搜索当前资讯流" /><button type="submit">搜索</button></form></van-popup>
  </main>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { useNewsStore } from '../store/modules/news'
import NewsItem from '../components/NewsItem.vue'
import TabBar from '../components/TabBar.vue'
const newsStore = useNewsStore(); const router = useRouter(); const showSearch = ref(false); const keyword = ref(''); let refreshTimer
const updateLabel = computed(() => newsStore.lastUpdated ? `更新于 ${newsStore.lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : '正在连接资讯源')
const refresh = () => newsStore.getNewsList(true)
const doSearch = () => { const term = keyword.value.trim(); if (!term) return; sessionStorage.setItem('search-source', JSON.stringify(newsStore.newsList)); showSearch.value = false; router.push({ path: '/search', query: { q: term } }) }
watch(showSearch, visible => { if (!visible) keyword.value = '' })
onMounted(async () => { await newsStore.getCategories(); await Promise.all([newsStore.getNewsList(true), newsStore.getTrending()]); refreshTimer = window.setInterval(() => newsStore.liveMode && newsStore.getNewsList(true), 120000) })
onBeforeUnmount(() => window.clearInterval(refreshTimer))
</script>
<style scoped>
