ckground:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:0 13px}.trend-label{color:#fff;background:#ff5b69;width:20px;height:20px;display:grid;place-items:center;border-radius:6px;font-size:12px;font-weight:bold}.trend-text{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.trend-strip :deep(.van-icon){color:#9da0af}.feed-head{margin:18px 2px 9px}.feed-head strong{display:block;font-size:18px}.feed-head small{font-size:11px;color:#a0a4b2}.feed-head button{border:0;background:transparent;color:#b6a4ff;font-size:12px}.empty-state{text-align:center;padding:48px 0;color:#b6bbd0}.empty-state :deep(.van-icon){font-size:35px}.empty-state button{border:0;border-radius:9px;padding:8px 14px;color:#fff;background:#7658f8}.search-box{gap:10px;padding:14px 20px;background:#111323}.search-box input{flex:1;border:0;outline:0;font-size:16px;background:transparent;color:#fff}.search-box button{border:0;background:#7055ec;color:#fff;border-radius:9px;padding:8px 13px}
</style>
